(7201846, 1107792, 3724, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=753886" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg"/></a> <br/> <br/>Enjoy the sophisticated pervading mood and tone, with obvious technical awareness. gave 9.</td>', '  Enjoy the sophisticated pervading mood and tone, with obvious technical awareness. gave 9.', '2014-04-11 02:42:19.000000', NULL, 0),
(7201850, 1107844, 77185, '<td valign="top">This is a lovely capture, Bear. :)</td>', 'This is a lovely capture, Bear. :)', '2014-04-11 02:46:41.000000', NULL, 0),
(7201897, 1107790, 163430, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by nam:</b></div><hr/><i> I gave this one of my top scores (9 and I only had two 10''s in the challenge) and hoped it would be higher - but I was afraid it wasn''t "fence" enough for many.  I do adore the depth of field and though I am not usually all that fond of selective color, I think it works nicely here.  Nice finish. </i></td></tr></table> <br/> <br/>I knew it wasn''t a typical fence shot, but i went for it anyways. The more standard ones that i made i didn''t like. 6+ is a decent score. Finished in the Top20. The depth of field was slightly tuned in post processing. Just slightly. As for the selective color, i''m kind of a sucker for it. I love it. I made a version with the gold color left on the "fence" (actually it''s a bridge railing). It was too shiny. This way, the red padlock really stands out.<br/> <br/>For the curious ones, the writings are in Cyrillic and it says: Moni Viktor. Moni is short for Monika i guess.<br/><br/><i>Message edited by author 2014-04-11 04:13:35.</i></td>', 'Originally posted by nam: I gave this one of my top scores (9 and I only had two 10''s in the challenge) and hoped it would be higher - but I was afraid it wasn''t "fence" enough for many.  I do adore the depth of field and though I am not usually all that fond of selective color, I think it works nicely here.  Nice finish.   I knew it wasn''t a typical fence shot, but i went for it anyways. The more standard ones that i made i didn''t like. 6+ is a decent score. Finished in the Top20. The depth of field was slightly tuned in post processing. Just slightly. As for the selective color, i''m kind of a sucker for it. I love it. I made a version with the gold color left on the "fence" (actually it''s a bridge railing). It was too shiny. This way, the red padlock really stands out. For the curious ones, the writings are in Cyrillic and it says: Moni Viktor. Moni is short for Monika i guess.', '2014-04-11 05:12:47.000000', '2014-04-11 05:13:35.000000', 0),
(7201988, 1107792, 158423, '<td valign="top">Thank you for the award, <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=3724" rel="nofollow" target="_blank">undieyatch</a>. And for the vote! It means a lot to me...</td>', 'Thank you for the award,  undieyatch. And for the vote! It means a lot to me...', '2014-04-11 11:16:50.000000', NULL, 0),
